CREATE OR REPLACE FUNCTION public.handle_new_xmd_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name, business_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data ->> 'display_name', ''), COALESCE(NEW.raw_user_meta_data ->> 'business_name', '')) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$;
REVOKE EXECUTE ON FUNCTION public.handle_new_xmd_user() FROM PUBLIC, anon, authenticated;
